contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt a withdrawal of `amount`; if it succeeds, balance decreases by exactly amount and depositsCount unchanged.
    function run(uint amount) public payable {
        // bound amount to avoid underflow reasoning complexity
        require(amount <= address(c).balance, "amount too large");

        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Single simple general assertion:
        // If call did not revert then balance decreased exactly by amount and depositsCount unchanged.
        assert(reverted || (afterBal == beforeBal - amount && afterDeposits == beforeDeposits));
    }

    receive() external payable {}
}

